"OLAYLAR_DUNYA_AVRUPA_MO:-0549-01-01:0":{"b": ["Miltiades (Yaşlı) Frakiya Xersonesosunda hakimiyyət qurdu", "6da9fbe4"], "d": ["Afina əsilli Miltiades Gəlibolu yarımadasında yarımmüstəqil idarəçilik qurdu.", "88847c09"]},
