"OLAYLAR_DUNYA_AVRUPA_MO:-0573-01-01:0":{"b": ["Emporion (Ampurias) fokaiyalılar tərəfindən quruldu", "c4706f54"], "d": ["Massaliyanın İber sahilində məskəni; Hispaniyada Yunan varlığı.", "525d2aff"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0593-01-01:0":{"b": ["Solonun arxonluğu və seisaxtheia islahatları", "705d0dbf"], "d": ["Borc köləliyini ləğv edən islahatlar; vətəndaş sinifləri yenidən nizamlandı.", "6d544b32"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0594-01-01:0":{"b": ["Birinci Müqəddəs Müharibə: Kirrha dağıdıldı, Delfi Amfiktiyoniya nəzarətinə keçdi", "e01a15f5"], "d": ["Delfiyə giriş üçün Kirrha məhv edildi.", "1ad355f7"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0597-01-01:0":{"b": ["Kamarina Sirakuza tərəfindən quruldu", "47055e49"], "d": ["Sirakuza cənub-şərqdə koloniya qurdu (Sirakuzadan 135 il sonra).", "40d8cb35"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0599-01-01:0":{"b": ["Poseidoniya (Paestum) sibarislilər tərəfindən quruldu", "5a2f0a73"], "d": ["Sibaris Tirren sahilində koloniya qurdu.", "3a48417e"]},
